// src/store/userStore.js
import { reactive } from "vue";
import axios from "axios"; // 引入 Axios

// 从 localStorage 中获取用户数据并解析
const storedUserData = localStorage.getItem("userStore");
let initialUser = {};

if (storedUserData) {
  try {
    initialUser = JSON.parse(storedUserData); // 尝试解析 JSON
  } catch (error) {
    console.error("无法解析用户数据:", error);
    // 解析失败，initialUser 保持为空对象
  }
}

const state = reactive({
  user: initialUser, // 初始化用户数据
});

// 定义 mutations
const mutations = {
  setUser(state, userData) {
    state.user = userData; // 设置用户数据
    localStorage.setItem("userStore", JSON.stringify(userData)); // 更新 localStorage
  },
  clearUser(state) {
    state.user = {}; // 清除用户数据
    localStorage.removeItem("userStore"); // 同步清除 localStorage
  },
};

// 定义 actions
const actions = {
  async login({ commit }, loginData) {
    try {
      const response = await axios.post(
        "/api/auth/login",
        {
          // 直接在这里调用后端登录接口
          username: loginData.username,
          password: loginData.password,
        },
      );
      commit("setUser", response.data); // 保存用户数据到 Vuex
      return response.data; // 返回响应数据
    } catch (error) {
      console.error("登录失败:", error);
      throw new Error(
        error.response ? error.response.data.message : "登录失败",
      ); // 更具体的错误处理
    }
  },
  logout({ commit }) {
    commit("clearUser"); // 清除用户数据
  },
};

// 定义 getters
const getters = {
  user(state) {
    return state.user; // 直接返回用户数据
  },
  userPhoneNumber(state) {
    return state.user ? state.user.phoneNumber : null; // 获取用户电话
  },
  userId(state) {
    return state.user ? state.user.id : null; // 获取用户 ID
  },
  userBalance(state) {
    return state.user ? state.user.AccountBalance : null; // 获取用户余额
  },
  userNickname(state) {
    return state.user ? state.user.nickname : "用户"; // 获取用户昵称
  },
  userAvatar(state) {
    return state.user ? state.user.avatar : "/assets/avatar.png"; // 获取用户头像
  },
};

// 导出对象
export default {
  state,
  mutations,
  actions,
  getters,
};
